import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { Job } from 'src/app/landing/models/job';
import { JobService } from 'src/app/service/job/job.service';

@Component({
  selector: 'app-saved-jobs',
  templateUrl: './saved-jobs.component.html',
  styleUrls: ['./saved-jobs.component.css']
})
export class SavedJobsComponent {

  savedJobs: Job[] = [];
  totalSavedJobs = 0;
  jobseekerId = Number(localStorage.getItem('id'));

  constructor(
    private jobService: JobService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.getAllSavedJobs(this.jobseekerId);
  }

  logout(): void {
    localStorage.clear();
    this.router.navigate(['/']);
  }

  getAllSavedJobs(jobSeekerId: number): void {
    this.jobService.getSavedJobs(jobSeekerId).subscribe({
      next: (result) => {
        this.savedJobs = result;
        this.totalSavedJobs = this.savedJobs.length;
      },
      error: (err) => {
        console.log(err);
      }
    });
  }

  removeSavedJob(jobId: number): void {
    this.jobService.removeSavedJob(jobId, this.jobseekerId).subscribe({
      next: () => {
        this.savedJobs = this.savedJobs.filter(
          job => Number(job.jobId) !== Number(jobId)
        );
        this.totalSavedJobs = this.savedJobs.length;
      },
      error: (err) => {
        console.log(err);
      }
    });
  }
}
<div class="page">
  <app-header variant="guest"></app-header>

  <div class="app-shell">
    <main class="main">

      <div class="page-title">Saved Jobs</div>
      <div class="page-sub">{{totalSavedJobs}} roles you've bookmarked to apply to later.</div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Role</th>
              <th>Company</th>
              <th>Salary</th>
              <th>Saved On</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let job of savedJobs">
              <td>{{job.jobTitle}}</td>
              <td>{{job.companyName}}</td>
              <td>{{job.salary | currency}}</td>
              <td>2 days ago</td>
              <td class="actions">
                <a [routerLink]="['/job/view-job', job.jobId]">Apply</a><a class="danger" style="cursor: pointer;" (click)="removeSavedJob(+job.jobId)">Remove</a>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

    </main>
  </div>
</div>
